import type { CoursePracticeQuestion, StructuredLessonSection } from "./cisc1115Course.ts";
import type { ProfessorTrackAddedChapter } from "./cisc1115ProfessorTrack.ts";
import { validateClassroomJava, type ClassroomSample, type ClassroomSpec } from "../classroomJavaValidation.ts";
import { bookQuestion, conversionQuestion, classroomValidationFixtures, textPracticeAdditions } from "./cisc1115MidtermMaterial.ts";

type Level = CoursePracticeQuestion["level"];
type Fixture = { spec: ClassroomSpec; samples: ClassroomSample[] };
export const studyGuideValidationFixtures = new Map<string, Fixture>();
export const studyGuideTraceFixtures = new Map<string, { code: string; output: string; files?: Record<string, string>; input?: string }>();
const normalize = (s: string) => s.trim().replace(/\r/g, "").split("\n").map(s => s.trimEnd()).join("\n");
const id = (s: string) => `study-guide-${s}`;
const output = (key: string, title: string, code: string, answer: string, hint: string, level: Level = "Apply", prompt = "What is the exact output?"): CoursePracticeQuestion => {
  studyGuideTraceFixtures.set(id(key), { code, output: answer });
  return { id: id(key), title, code, answer, hint, level, prompt, kind: "Predict exact output", placeholder: "Type the output", multiline: answer.includes("\n"), success: "Correct. You followed the executed statements, values, and types.", validate: s => normalize(s) === answer };
};
const select = (key: string, title: string, prompt: string, answer: string, distractors: string[], hint: string, code?: string): CoursePracticeQuestion => {
  const choices = [answer, ...distractors], shift = [...key].reduce((sum, c) => sum + c.charCodeAt(0), 0) % choices.length;
  return { id: id(key), title, prompt, code, answer, hint, level: "Warm-up", kind: "Multiple choice", options: [...choices.slice(shift), ...choices.slice(0, shift)], placeholder: "Choose one answer", success: "Correct. That matches the Java behavior.", validate: s => s.trim() === answer };
};
const write = (key: string, title: string, prompt: string, answer: string, spec: ClassroomSpec, samples: ClassroomSample[], hint: string, code?: string, level: Level = spec.className ? "Challenge" : "Apply"): CoursePracticeQuestion => {
  studyGuideValidationFixtures.set(id(key), { spec, samples });
  return { id: id(key), title, prompt, code, answer, hint, level, kind: spec.className ? "Complete Java program" : "Write Java code", multiline: true, productionStage: spec.className ? 5 : code ? 3 : 4, auditRequirements: ["Results across input and boundary cases", "Only midterm tools"], placeholder: spec.className ? "Write the complete Java source file" : "Write the requested Java code", success: "Your solution meets the behavior across the tested cases.", validate: s => validateClassroomJava(s, spec, samples) };
};
const full = (name: string, body: string, files = false) => `${files ? "import java.io.File;\nimport java.io.PrintWriter;\nimport java.io.FileNotFoundException;\n" : ""}import java.util.Scanner;\n\npublic class ${name} {\n    public static void main(String[] args)${files ? " throws FileNotFoundException" : ""} {\n${body.split("\n").map(s => "        " + s).join("\n")}\n    }\n}`;
const numericCases = (values: ClassroomSample["values"][], calculate: (v: NonNullable<ClassroomSample["values"]>) => number | boolean | string) => values.map(v => ({ values: v, result: calculate(v!) }));
const anchored = (key: string, q: CoursePracticeQuestion): CoursePracticeQuestion => {
  const fixture = classroomValidationFixtures.get(q.id);
  if (fixture) studyGuideValidationFixtures.set(id(key), fixture);
  return { ...q, id: id(key), title: `Study Guide: ${q.title.replace("Class Practice: ", "")}` };
};
const number = (key: string, title: string, prompt: string, answer: string, base: 2 | 10 | 16, hint: string, level: Level = "Apply"): CoursePracticeQuestion => ({
  id: id(key), title, prompt, answer, hint, level, kind: "Convert or calculate", placeholder: `Enter the base-${base} result`, success: "Correct. The positional values and carries agree.",
  validate: s => { const digits = s.trim().replace(base === 2 ? /^0b/i : base === 16 ? /^0x/i : /^$/, ""); return (base === 2 ? /^[01]+$/ : base === 16 ? /^[\da-f]+$/i : /^\d+$/).test(digits) && parseInt(digits, base) === parseInt(answer, base); },
});
// Result/type questions accept literal notation as well as the displayed value.
const typed = (key: string, title: string, declarations: string, expression: string, value: string, type: "String" | "char" | "int", hint: string, level: Level = "Apply"): CoursePracticeQuestion => ({
  id: id(key), title, code: `${declarations}\n// Expression to evaluate:\n${expression}`, level, kind: "Predict value and type", prompt: "Give the value and its type as VALUE | TYPE. Quotes around a String or char value are optional. Use double quotes for an empty String.", answer: `${value === "" ? '""' : value} | ${type}`, hint, placeholder: "VALUE | TYPE", success: "Correct. Both the returned value and its type match.",
  validate: s => { const parts = s.trim().split(/\s*\|\s*|\r?\n/); if (parts.length !== 2 || parts[1].trim().toLowerCase() !== type.toLowerCase()) return false; let submitted = parts[0].trim(); if ((submitted.startsWith('"') && submitted.endsWith('"')) || (submitted.startsWith("'") && submitted.endsWith("'"))) submitted = submitted.slice(1, -1); return submitted === value; },
});
type Group = { reference: string; section: StructuredLessonSection; questions: CoursePracticeQuestion[] };
export const studyGuideGroups: Group[] = [];
const group = (reference: string, key: string, section: Omit<StructuredLessonSection, "id">, questions: CoursePracticeQuestion[]) => studyGuideGroups.push({ reference, section: { ...section, id: id(key) }, questions });

group("Topic checklist · page 1", "toolkit", {
  eyebrow: "Start here · the small rules behind the big questions", title: "Program, Types, Operators, and Boolean Refresher",
  lead: "The guide combines familiar Java tools. A declaration gives a variable a type; an assignment changes its value; an expression produces a value. Read each expression's type before deciding what it prints or where it can be stored. These short checks lead into the seven guide problem families below; you can open any family directly.",
  concepts: [{ label: "Numeric rules", detail: "int / int discards the fraction before assignment. A double operand makes the division decimal. % produces a remainder." }, { label: "Updates", detail: "x++ supplies the old value and then updates x; ++x updates first. += and related operators store the new result." }, { label: "Booleans", detail: "&& requires both, || accepts either or both, ^ accepts exactly one, and ! reverses. Group long conditions with parentheses." }, { label: "Program wrapper", detail: "A public class name matches its .java filename. main is the entry point. import java.util.Scanner makes the Scanner class name available." }],
  examples: [{ label: "A decimal result needs decimal division", code: "int total = 9;\nint count = 2;\ndouble first = total / count;          // 4.0\ndouble second = (double) total / count; // 4.5", note: "The destination being double does not change how the right side was evaluated." }, { label: "Store a decision result", code: "int age = 20;\nboolean hasId = true;\nboolean admitted = age >= 18 && hasId;\nSystem.out.println(admitted); // true" }],
  rules: ["Unless stated otherwise, code-writing problems allow any equivalent structure using these early tools.", "No loops, arrays, or custom method definitions are needed in this study guide."]
}, [
  select("type-quotes", "Keep char and String Separate", "Which pair of declarations compiles?", "char initial = 'D'; String name = \"Daniel\";", ["char initial = \"D\"; String name = 'Daniel';", "char initial = 'DL'; String name = \"Daniel\";", "char initial = D; String name = Daniel;"], "A char literal has one character in single quotes."),
  output("division", "Trace the Division Before Assignment", "int a = 9;\nint b = 2;\ndouble result = a / b;\nSystem.out.println(result);", "4.0", "The division has two int operands.", "Warm-up"),
  write("average", "Preserve a Fraction", "Given int total and int count (count > 0), declare double average containing their mathematical quotient.", "double average = (double) total / count;", { types: { total: "int", count: "int" }, resultVariable: "average", resultType: "double" }, numericCases([{ total: 9, count: 2 }, { total: -3, count: 2 }, { total: 0, count: 4 }], v => Number(v.total) / Number(v.count)), "Convert before division; a cast after int division is too late."),
  output("updates", "Separate the Saved Value from the Update", "int a = 4;\nint b = a++;\nint c = ++a;\nb += c;\nSystem.out.println(a + \" \" + b + \" \" + c);", "6 10 6", "b initially receives 4; c receives the later value 6."),
  output("concatenation", "Arithmetic or Text Joining?", "System.out.println(2 + 3 + \" pts\");\nSystem.out.println(\"pts \" + 2 + 3);\nSystem.out.println(\"pts \" + (2 + 3));", "5 pts\npts 23\npts 5", "Parentheses decide whether the addition happens before joining text."),
  output("boolean-precedence", "Trace AND Before OR", "System.out.println(true || false && false);\nSystem.out.println((true || false) && false);\nSystem.out.println(true ^ true);", "true\nfalse\nfalse", "Grouping changes the first two expressions. XOR rejects both true."),
  write("outside-range", "Recognize an Outside Range", "Given int score, declare boolean invalid true only when score is outside 0 through 100 inclusive.", "boolean invalid = score < 0 || score > 100;", { types: { score: "int" }, resultVariable: "invalid", resultType: "boolean" }, numericCases([-1, 0, 50, 100, 101].map(score => ({ score })), v => Number(v.score) < 0 || Number(v.score) > 100), "An outside value misses the lower end OR the upper end."),
  write("union-actors", "Combine Alternatives with a Requirement", "Given int age and boolean unionized, declare boolean eligible for a unionized actor younger than 23 or older than 55. Ages 23 through 55 do not qualify.", "boolean eligible = unionized && (age < 23 || age > 55);", { types: { age: "int", unionized: "boolean" }, resultVariable: "eligible", resultType: "boolean" }, numericCases([true, false].flatMap(unionized => [22, 23, 55, 56].map(age => ({ age, unionized }))), v => Boolean(v.unionized) && (Number(v.age) < 23 || Number(v.age) > 55)), "Union membership must apply to BOTH age alternatives."),
  write("exactly-one", "Choose Exactly One Delivery Method", "Given boolean pickup and delivery, declare boolean valid when exactly one is selected. Either equivalent Boolean logic or XOR is allowed.", "boolean valid = pickup ^ delivery;", { types: { pickup: "boolean", delivery: "boolean" }, resultVariable: "valid", resultType: "boolean" }, numericCases([true, false].flatMap(pickup => [true, false].map(delivery => ({ pickup, delivery }))), v => v.pickup !== v.delivery), "Neither selected and both selected are the two invalid cases."),
  select("uninitialized", "Declaration Does Not Supply a Local Value", "Why does the shown code fail to compile?", "maximum may be uninitialized when a <= b", ["int variables cannot be printed", "The comparison must use =", "A local int automatically contains 0"], "Every path that reaches the print needs a value for maximum.", "int a = 2;\nint b = 5;\nint maximum;\nif (a > b) { maximum = a; }\nSystem.out.println(maximum);")
]);

export const guideNestedCode = `int a = 12;
int b = 50;
double c = 0;
if (a % 2 == 1) {
    if (b > 10) { c = b + 2; b += 2; }
    else { c = a * 2; b--; }
} else {
    if (b != 50) { c = b + 1; b -= 1; }
    else if (b >= 50) { c = a - 1; a -= 1; }
    a *= 2;
}
if (a % 2 == 1) { b = 0; } else { b = 1; }`;
const nestedFinal = "\nSystem.out.println(a + \" \" + b + \" \" + c);";
const historyAnswer = "a=12\nb=50\nc=0.0\nc=11.0\na=11\na=22\nb=1";
const history: CoursePracticeQuestion = { id: id("guide-history"), title: "Study Guide Q1: Every Changed Value", level: "Challenge", kind: "Trace variable history", code: guideNestedCode, prompt: "List each initialized or changed variable in execution order as name=value, one per line. Include initial declarations; record only statements that execute. Display c as a double.", answer: historyAnswer, hint: "Start with a=12, b=50, c=0.0. Update your notes immediately after each executed assignment; skipped branches add no entries.", placeholder: "a=...\nb=...\nc=...", multiline: true, success: "Correct. Your history follows the actual branch and subsequent updates.", validate: s => normalize(s).replace(/\s*=\s*/g, "=") === historyAnswer };
studyGuideTraceFixtures.set(history.id, { code: guideNestedCode.replace(/((?:(?:int|double)\s+)?([abc])\s*(?:=[^;]+|\+=\s*2|-=\s*1|\*=\s*2|--)\s*;)/g, '$1 System.out.println("$2=" + $2);'), output: historyAnswer });

group("Q1 · pages 2 and 7", "trace", {
  eyebrow: "Guide Q1 · follow the current state", title: "Trace Changing Variables and Nested Branches",
  lead: "A trace table records execution, not indentation or every line on the page. Start with the declarations, decide which branch runs, and update the current values immediately. A later condition reads the updated variable, not its original value. An else belongs to its matching if; braces decide which updates run after an inner branch.",
  examples: [{ label: "Record only executed changes", code: "int x = 6;\nint y = 4;\nif (x % 2 == 0) {\n    y += x;\n    x--;\n} else {\n    y = 0;\n}\n// Trace: x=6, y=4, y=10, x=5", note: "The else assignment never executes. A later parity check would see x=5." }],
  rules: ["Use a separate row for each executed change, including ++, -- and compound assignments.", "After an earlier test fails, use that information to eliminate impossible later cases.", "Do not run every true-looking branch in an else-if chain."]
}, [
  output("trace-basic", "Update Before Comparing Again", "int n = 6;\nn--;\nif (n % 2 == 0) { System.out.println(\"Even\"); }\nelse { System.out.println(\"Odd\"); }", "Odd", "The condition sees 5, not 6.", "Warm-up"),
  output("trace-independent", "Two Decisions Can Both Run", "int n = 4;\nif (n > 0) { n += 3; }\nif (n > 5) { n *= 2; }\nSystem.out.println(n);", "14", "The second if reads the first if's updated value."),
  output("trace-chain", "A Chain Chooses One Branch", "int n = 4;\nif (n > 0) { n += 3; }\nelse if (n > 5) { n *= 2; }\nSystem.out.println(n);", "7", "The else-if is skipped after the first branch is selected."),
  output("trace-inner-else", "Follow an Else Inside a Branch", "int a = 9, b = 8;\nif (a % 2 == 1) {\n    if (b > 10) { b += 2; } else { b--; }\n}\nSystem.out.println(a + \" \" + b);", "9 7", "The outer test succeeds; the inner test fails."),
  output("trace-after-inner", "Find What Runs After the Inner Decision", "int a = 8;\nint b = 20;\nif (a % 2 == 0) {\n    if (b > 50) { a--; }\n    a *= 2;\n}\nSystem.out.println(a);", "16", "The multiplication belongs to the outer block."),
  output("trace-parity", "Carry a Changed Value Forward", "int a = 8;\nif (a % 2 == 0) { a--; }\nint b = a % 2 == 0 ? 1 : 0;\nSystem.out.println(a + \" \" + b);", "7 0", "The final expression sees the odd value 7."),
  output("guide-final", "Study Guide Q1: Final State", guideNestedCode + nestedFinal, "22 1 11.0", "a starts even; b equals 50. Follow the selected inner branch, then the multiplication.", "Challenge"),
  history,
  output("trace-odd-large", "Variation: Outer True, Inner True", guideNestedCode.replace("a = 12", "a = 9").replace("b = 50", "b = 12") + nestedFinal, "9 0 14.0", "The first outer branch runs; the final if later overwrites b.", "Challenge"),
  output("trace-odd-small", "Variation: The Inner Else", guideNestedCode.replace("a = 12", "a = 9").replace("b = 50", "b = 8") + nestedFinal, "9 0 18.0", "c receives a*2; the final parity decision changes b again.", "Challenge"),
  output("trace-even-not50", "Variation: An Earlier Failure Changes the Path", guideNestedCode.replace("a = 12", "a = 8").replace("b = 50", "b = 49") + nestedFinal, "16 1 50.0", "b != 50 succeeds, so the following else-if is never tested.", "Challenge"),
  write("repair-maximum", "Repair a Missing Path", "Given int first and second, replace the broken fragment with code that declares int maximum containing the larger input, including equal and negative inputs. Choose your own structure.", "int maximum;\nif (first > second) { maximum = first; } else { maximum = second; }", { types: { first: "int", second: "int" }, resultVariable: "maximum", resultType: "int" }, numericCases([{ first: 3, second: 8 }, { first: 8, second: 3 }, { first: -2, second: -7 }, { first: 4, second: 4 }], v => Math.max(Number(v.first), Number(v.second))), "Cover both comparison outcomes before the value is used.", "int maximum;\nif (first > second) { maximum = first; }", "Challenge")
]);

group("Q2 · pages 3 and 8", "menus", {
  eyebrow: "Guide Q2 · input, selection, result", title: "Build Text Menus and Complete Programs",
  lead: "A text menu has three jobs: read the user's values, recognize a supported choice, and produce exactly one result. Use equals for String contents. Unknown choices need their own outcome; they must not silently use the last conversion factor. A complete program includes import, the named class, main, input setup, decisions and output.",
  examples: [{ label: "A smaller menu with an invalid choice", code: full("LengthMenu", "Scanner input = new Scanner(System.in);\ndouble centimeters = input.nextDouble();\nString unit = input.next();\nif (unit.equals(\"meters\")) {\n    System.out.println(centimeters / 100 + \" meters\");\n} else {\n    System.out.println(\"Invalid conversion\");\n}"), note: "The guide's full problem adds more choices. A different class name requires a matching filename." }],
  rules: ["next() reads one token; nextLine() preserves a whole line.", "The prompt states whether capitalization matters. Do not assume a case policy.", "In these program tasks, optional input prompts may precede the input. The grader checks the required result after input."]
}, [
  select("menu-compare", "Recognize Text Contents", "Given String unit from input, which check recognizes the exact word feet?", 'unit.equals("feet")', ['unit == "feet"', 'unit.equals("Feet")', "unit = feet"], "Input text is compared by content."),
  output("menu-trace", "Follow a Supported Choice", "double meters = 2;\nString unit = \"feet\";\nif (unit.equals(\"inches\")) { System.out.println(meters * 39.37); }\nelse if (unit.equals(\"feet\")) { System.out.println(meters * 3.28); }\nelse { System.out.println(\"Invalid conversion\"); }", "6.56", "Only the feet branch runs."),
  output("menu-invalid", "Do Not Treat an Unknown Choice as a Default Unit", "double meters = 2;\nString unit = \"yards\";\nif (unit.equals(\"inches\")) { System.out.println(meters * 39.37); }\nelse if (unit.equals(\"feet\")) { System.out.println(meters * 3.28); }\nelse { System.out.println(\"Invalid conversion\"); }", "Invalid conversion", "yards matches neither supported word."),
  write("menu-repair", "Repair a Text-Comparison Bug", "Given String unit, print Feet only for the exact word feet; otherwise print Other. Repair the shown logic.", 'if (unit.equals("feet")) { System.out.println("Feet"); } else { System.out.println("Other"); }', { types: { unit: "String" } }, ["feet", "Feet", "miles", ""].map(unit => ({ values: { unit }, output: unit === "feet" ? "Feet" : "Other" })), "String identity is not content equality.", 'if (unit == "feet") { System.out.println("Feet"); } else { System.out.println("Other"); }'),
  write("menu-factor", "Select a Factor Without Printing Yet", "Given String unit containing inches, feet, or miles, declare double factor containing 39.37, 3.28, or 0.000621 respectively. Inputs are guaranteed to be one of these three words.", 'double factor;\nif (unit.equals("inches")) { factor = 39.37; }\nelse if (unit.equals("feet")) { factor = 3.28; }\nelse { factor = 0.000621; }', { types: { unit: "String" }, resultVariable: "factor", resultType: "double" }, ["inches", "feet", "miles"].map((unit, i) => ({ values: { unit }, result: [39.37, 3.28, .000621][i] })), "Assign a value on every valid path."),
  anchored("guide-conversion", conversionQuestion),
  write("menu-temperature", "Build a Different Conversion Menu", "Write TemperatureMenu.java. Read a decimal Celsius temperature, then a case-sensitive token fahrenheit or kelvin. Print the numeric converted value followed by a space and that unit. Fahrenheit = Celsius*9.0/5+32; Kelvin = Celsius+273.15. For any other token, print Invalid conversion. Optional prompts may precede input.", full("TemperatureMenu", 'Scanner input = new Scanner(System.in);\ndouble c = input.nextDouble();\nString unit = input.next();\nif (unit.equals("fahrenheit")) { System.out.println(c * 9.0 / 5 + 32 + " fahrenheit"); }\nelse if (unit.equals("kelvin")) { System.out.println(c + 273.15 + " kelvin"); }\nelse { System.out.println("Invalid conversion"); }'), { className: "TemperatureMenu" }, [{ input: "0 fahrenheit", output: "32.0 fahrenheit" }, { input: "100 fahrenheit", output: "212.0 fahrenheit" }, { input: "-40 fahrenheit", output: "-40.0 fahrenheit" }, { input: "0 kelvin", output: "273.15 kelvin" }, { input: "0.5 fahrenheit", output: "32.9 fahrenheit" }, { input: "10 rankine", output: "Invalid conversion" }], "Retrieve the full wrapper and preserve decimal arithmetic in the Fahrenheit formula."),
  write("menu-normalized", "Handle a Whole-Line Choice", "Write DistanceMenu.java. Read a nonnegative distance in meters on one line, then the full-line choice inches or feet on the next. Ignore surrounding spaces and capitalization in the choice. Print the result as one number, or Invalid conversion for an unknown choice. Use factors 39.37 and 3.28. Optional prompts may precede input.", full("DistanceMenu", 'Scanner input = new Scanner(System.in);\ndouble distance = input.nextDouble();\ninput.nextLine();\nString choice = input.nextLine().trim();\nif (choice.equalsIgnoreCase("inches")) { System.out.println(distance * 39.37); }\nelse if (choice.equalsIgnoreCase("feet")) { System.out.println(distance * 3.28); }\nelse { System.out.println("Invalid conversion"); }'), { className: "DistanceMenu", numericOutput: true }, [{ input: "2\n  FEET  \n", output: "6.56" }, { input: "1\nInChEs\n", output: "39.37" }, { input: "0\n feet \n", output: "0.0" }, { input: "1\nnautical miles\n", output: "Invalid conversion" }], "Account for the remainder of the numeric line before reading and normalizing the menu line.")
]);

group("Q3 · pages 3 and 8", "bases", {
  eyebrow: "Guide Q3 · value, representation, carries", title: "Binary, Decimal, Hexadecimal, and Binary Addition",
  lead: "The same quantity can have different digit representations. For binary, the places from right to left are 1, 2, 4, 8, 16, 32, 64, 128, 256. In hexadecimal they are 1, 16, 256; A through F mean 10 through 15. Always name the input and output bases before calculating.",
  examples: [{ label: "Choose positions, then check them", language: "Number systems", code: "86 = 64 + 16 + 4 + 2\n86 decimal = 1010110 binary\n\n9C hexadecimal = 9*16 + 12 = 156 decimal\n156 = 9*16 + 12, so 156 decimal = 9C hex", note: "An unused position needs a zero. A leading zero changes the written width, not the value." }, { label: "Carry in base two", language: "Binary", code: "  1011\n+ 0111\n------\n 10010", note: "1+1 is 10 in binary. If a column totals 3 with a carry, write 1 and carry 1." }],
  rules: ["For decimal to binary, choose powers of two from largest to smallest or use repeated division by 2.", "For decimal to hex, divide by 16 and keep remainders; write the last remainder first.", "Line up addition at the right edge. Check by converting both operands and the result to decimal.", "These answers accept leading zeroes, upper/lowercase hex, and optional 0b/0x prefixes."]
}, [
  number("binary-place", "Start with One Active Position", "Convert 00100000 from binary to decimal.", "32", 10, "The active position is worth 32.", "Warm-up"),
  number("binary-combination", "Keep the Zero Positions", "Convert 101001 from binary to decimal.", "41", 10, "Add 32 + 8 + 1."),
  number("binary-guide", "Study Guide Q3a: Binary to Decimal", "Convert 01010010 from binary to decimal.", "82", 10, "The active positions are 64, 16 and 2."),
  number("binary-edge", "One Place Beyond a Byte", "Convert 100000000 from binary to decimal.", "256", 10, "The ninth place from the right is 256."),
  number("hex-digit", "Give a Hex Letter Its Numeric Value", "Convert hexadecimal E to decimal.", "14", 10, "A is 10, so E is 14.", "Warm-up"),
  number("hex-guide", "Study Guide Q3b: Hex to Decimal", "Convert BF from hexadecimal to decimal.", "191", 10, "B*16 + F = 11*16 + 15."),
  number("hex-three", "Use the 256 Position", "Convert 10A from hexadecimal to decimal.", "266", 10, "There is one group of 256, no groups of 16, and ten ones.", "Challenge"),
  number("decimal-binary-guide", "Study Guide Q3c: Decimal to Binary", "Convert decimal 73 to binary.", "1001001", 2, "73 = 64 + 8 + 1."),
  number("decimal-binary-zero", "Represent Zero", "Convert decimal 0 to binary.", "0", 2, "Zero still needs a digit.", "Warm-up"),
  number("decimal-binary-gaps", "Preserve an Empty Middle Position", "Convert decimal 130 to binary.", "10000010", 2, "130 = 128 + 2."),
  number("decimal-hex-guide", "Study Guide Q3d: Decimal to Hex", "Convert decimal 29 to hexadecimal.", "1D", 16, "29 = 1*16 + 13."),
  number("decimal-hex-max", "Use Letters in Both Places", "Convert decimal 255 to hexadecimal.", "FF", 16, "255 = 15*16 + 15."),
  number("decimal-hex-carry", "Cross into the Next Hex Place", "Convert decimal 256 to hexadecimal.", "100", 16, "The previous value was FF; the next needs the 256 place.", "Challenge"),
  number("binary-add-small", "Carry Once", "Add binary 101 + 11. Give the result in binary.", "1000", 2, "5+3 is 8. Check that the binary addition agrees."),
  number("binary-add-guide", "Study Guide Q3e: Binary Addition", "Add binary 110101 + 11100. Give the result in binary.", "1010001", 2, "53+28 is 81; use that as a check after doing the carries."),
  number("binary-add-cascade", "Carry Through Every Position", "Add binary 11111111 + 1. Give the result in binary.", "100000000", 2, "A carry propagates through all eight ones.", "Challenge")
]);

group("Q4 · pages 4 and 9; Lecture 8", "prices", {
  eyebrow: "Guide Q4 · cases and interval boundaries", title: "Prices, Nested Conditions, and Rule Priority",
  lead: "A pricing problem often has two independent dimensions: which item it is, and which time or eligibility rules apply. List the cases before choosing a structure. You may branch on the item first, the interval first, or calculate a base price and then adjust it. What matters is that every combination receives the required result.",
  examples: [{ label: "A window includes one end and excludes the other", code: "boolean discountTime = hour >= 12 && hour < 15;\n// 11: false; 12: true; 14: true; 15: false", note: "The bookstore guide uses its own 16-through-before-19 window; always use the endpoints stated in the question." }, { label: "Compute a base, then apply a separate rule", code: "double price;\nif (size.equals(\"small\")) { price = 4.0; } else { price = 6.0; }\nif (member) { price *= 0.5; }\nSystem.out.println(price);", note: "This avoids repeating the membership rule in both branches. Nesting can be clearer when each case has a different adjustment." }],
  rules: ["Inside a range requires AND; outside it requires OR.", "Test just before, exactly at, and just after each boundary.", "An exception or invalid input can take priority over a discount.", "In the guide's bookstore case, 16 is included and 19 is excluded, matching its answer-key conditions."]
}, [
  output("price-window-trace", "Trace Both Ends of a Window", "int time = 19;\nSystem.out.println(time >= 16 && time < 19);\ntime = 16;\nSystem.out.println(time >= 16 && time < 19);", "false\ntrue", "The upper endpoint is excluded.", "Warm-up"),
  write("price-window", "Write the Time Condition", "Given int time (0 through 23), declare boolean happyHour true from 16 inclusive to 19 exclusive.", "boolean happyHour = time >= 16 && time < 19;", { types: { time: "int" }, resultVariable: "happyHour", resultType: "boolean" }, numericCases([0, 15, 16, 18, 19, 23].map(time => ({ time })), v => Number(v.time) >= 16 && Number(v.time) < 19), "A single time must satisfy both bounds."),
  write("price-repair-range", "Repair the Always-True Window", "Given int time (0 through 23), replace the shown declaration so boolean happyHour is true only from 16 inclusive to 19 exclusive.", "boolean happyHour = time >= 16 && time < 19;", { types: { time: "int" }, resultVariable: "happyHour", resultType: "boolean" }, numericCases([0, 15, 16, 18, 19, 23].map(time => ({ time })), v => Number(v.time) >= 16 && Number(v.time) < 19), "With OR, values below the window still satisfy the other comparison.", "boolean happyHour = time >= 16 || time < 19;"),
  output("price-overlap", "One Chain Does Not Apply Two Discounts", "double price = 10;\nboolean member = true;\nboolean coupon = true;\nif (member) { price -= 2; }\nelse if (coupon) { price -= 1; }\nSystem.out.println(price);", "8.0", "The coupon branch is skipped after member succeeds."),
  anchored("guide-books", bookQuestion),
  write("price-calculated", "Vary the Base Prices and the Window", "Given String kind (adult or child) and int hour (0–23), print the ticket price as one number. Adult costs 12.0, child 8.0. From hour 10 inclusive to 13 exclusive, each price is 25% lower. Inputs are valid; choose the implementation.", 'double price = kind.equals("adult") ? 12.0 : 8.0;\nif (hour >= 10 && hour < 13) { price *= 0.75; }\nSystem.out.println(price);', { types: { kind: "String", hour: "int" }, numericOutput: true }, ["adult", "child"].flatMap(kind => [9, 10, 12, 13, 23].map(hour => ({ values: { kind, hour }, output: String((kind === "adult" ? 12 : 8) * (hour >= 10 && hour < 13 ? .75 : 1)) }))), "Translate 25% lower into the amount paid, then test both interval endpoints.", undefined, "Challenge"),
  write("price-exclusive-discount", "Choose the Strongest Discount", "Given boolean member and coupon, print a price as one number. The base is 20.0. Members pay 15.0; nonmembers with a coupon pay 18.0; all others pay 20.0. Membership takes priority and discounts do not stack.", 'if (member) { System.out.println(15.0); }\nelse if (coupon) { System.out.println(18.0); }\nelse { System.out.println(20.0); }', { types: { member: "boolean", coupon: "boolean" }, numericOutput: true }, [true, false].flatMap(member => [true, false].map(coupon => ({ values: { member, coupon }, output: String(member ? 15 : coupon ? 18 : 20) }))), "Think through the both-true case before choosing separate ifs or a chain.", undefined, "Challenge"),
  write("price-validation", "Validate Before a Discount Applies", "Given String kind and int hour, print Invalid for an unknown kind (only adult or child are legal) or an hour outside 0–23. Otherwise print the ticket price as one number: adult 12.0, child 8.0, with 25% off from hour 10 inclusive to 13 exclusive. Choices are case-sensitive.", 'if ((!kind.equals("adult") && !kind.equals("child")) || hour < 0 || hour > 23) { System.out.println("Invalid"); }\nelse {\n    double price = kind.equals("adult") ? 12.0 : 8.0;\n    if (hour >= 10 && hour < 13) { price *= 0.75; }\n    System.out.println(price);\n}', { types: { kind: "String", hour: "int" }, numericOutput: true }, ["adult", "child", "other"].flatMap(kind => [-1, 9, 10, 12, 13, 23, 24].map(hour => ({ values: { kind, hour }, output: kind === "other" || hour < 0 || hour > 23 ? "Invalid" : String((kind === "adult" ? 12 : 8) * (hour >= 10 && hour < 13 ? .75 : 1)) + ".0" }))), "Invalid data must never be turned into a discounted valid ticket.", undefined, "Challenge"),
  write("price-priority", "Handle an Exception to an Exception", "Given int level and booleans vip and banned, print Banned if banned. Otherwise VIP is Eligible at any level. A non-VIP is Too low below 20, Too high above 80, or Eligible for 20–80 inclusive. Choose the structure yourself.", 'if (banned) { System.out.println("Banned"); }\nelse if (vip) { System.out.println("Eligible"); }\nelse if (level < 20) { System.out.println("Too low"); }\nelse if (level > 80) { System.out.println("Too high"); }\nelse { System.out.println("Eligible"); }', { types: { level: "int", vip: "boolean", banned: "boolean" } }, [true, false].flatMap(banned => [true, false].flatMap(vip => [19, 20, 80, 81].map(level => ({ values: { level, vip, banned }, output: banned ? "Banned" : vip ? "Eligible" : level < 20 ? "Too low" : level > 80 ? "Too high" : "Eligible" })))), "Find the rule that can never be overridden, then handle the remaining cases.", undefined, "Challenge")
]);

const formulaValues = [{ b: 4, c: 6, d: 1, e: 2 }, { b: 1, c: 13, d: 2, e: 3 }, { b: -2, c: 1, d: 2, e: -4 }];
const formulaSpec: ClassroomSpec = { types: { b: "double", c: "double", d: "double", e: "double" }, resultVariable: "a", resultType: "double" };
const formulaCases = numericCases(formulaValues, v => Number(v.b) + Math.sqrt((Number(v.c) + 3) / (2 + Number(v.d)) - Number(v.e)));
group("Q5 · pages 4 and 9; Lectures 9–10", "math", {
  eyebrow: "Guide Q5 · translate the grouping", title: "Math Methods, Formula Translation, and Random Ranges",
  lead: "A formula's fraction bars and radical bars are grouping instructions. Translate those groups into parentheses before filling in the Java method names. In the actual Q5 diagram, the radical bar extends over the final subtraction: a = b + sqrt((c+3)/(2+d) - e). Its -e belongs inside Math.sqrt. The following variations deliberately move operations into and out of a radical.",
  concepts: [{ label: "Calls and returns", detail: "Math.pow(base, exponent), sqrt(x), exp(x), log(x), and log10(x) return double. exp means e raised to x; log is the natural logarithm and log10 is base ten." }, { label: "Rounding", detail: "floor goes toward negative infinity; ceil goes upward; rint chooses the nearest integer, using the even integer for a tie, and returns double. round(double) chooses the nearest long, with half ties toward positive infinity." }, { label: "Trigonometry", detail: "sin/cos/tan take radians. toRadians converts degrees first; asin/acos/atan return radians. toDegrees converts the returned angle to degrees." }, { label: "Random integers", detail: "Math.random() is a double from 0 inclusive to 1 exclusive. For low through high inclusive: (int)(Math.random()*(high-low+1))+low. Scale before casting." }],
  examples: [{ label: "Move a subtraction across the radical boundary", code: "// Given doubles x, y, z and valid square-root inputs:\ndouble inside = Math.sqrt(x / y - z);\ndouble outside = Math.sqrt(x / y) - z;", note: "These are different formulas. Use the visible extent of the radical bar, rather than assuming where it ends." }, { label: "Trace a fixed random sample", code: "double r = 0.81;\nint digit = (int) (r * 10); // 8, in 0 through 9\nint wrong = (int) r * 10;  // 0", note: "The upper endpoint of r*10 is excluded. Casting r before scaling destroys its fractional information." }],
  rules: ["Use Math.pow for exponentiation; ^ is Boolean XOR in this practice.", "All supplied formula inputs keep denominators nonzero and roots/logarithms in their valid domains.", "Use decimal division when the mathematical fraction must retain a fractional part."]
}, [
  output("math-powers", "Retrieve a Call's Value and Return Type", "System.out.println(Math.pow(2, 3));\nSystem.out.println(Math.sqrt(49));", "8.0\n7.0", "Both calls return double.", "Warm-up"),
  output("math-logs", "Trace Exponential and Logarithmic Calls", "System.out.println(Math.exp(0));\nSystem.out.println(Math.log(1));\nSystem.out.println(Math.log10(100));", "1.0\n0.0\n2.0", "e^0=1, ln(1)=0, and 10^2=100."),
  output("math-rounding", "Compare Negative Rounding and Casting", "double x = -2.5;\nSystem.out.println((int) x);\nSystem.out.println(Math.floor(x));\nSystem.out.println(Math.ceil(x));\nSystem.out.println(Math.round(x));", "-2\n-3.0\n-2.0\n-2", "Truncation, floor, ceil and nearest rounding are different operations."),
  output("math-rint", "Distinguish Two Tie Rules", "System.out.println(Math.rint(2.5));\nSystem.out.println(Math.round(2.5));\nSystem.out.println(Math.rint(3.5));", "2.0\n3\n4.0", "rint's tie goes to the even integer and returns double."),
  write("math-simple-root", "Write a Grouped Radical", "Given doubles x and y (y > 0, x >= 0), declare double value equal to sqrt(x/y).", "double value = Math.sqrt(x / y);", { types: { x: "double", y: "double" }, resultVariable: "value", resultType: "double" }, numericCases([{ x: 18, y: 2 }, { x: 1, y: 4 }, { x: 0, y: 3 }], v => Math.sqrt(Number(v.x) / Number(v.y))), "Keep the entire ratio as the argument to sqrt."),
  write("guide-formula", "Study Guide Q5: Translate the Actual Radical", "Given doubles b, c, d and e, declare double a for a = b + sqrt((c+3)/(2+d) - e). The square root covers BOTH the ratio and the final subtraction; assume valid inputs.", "double a = b + Math.sqrt((c + 3) / (2 + d) - e);", formulaSpec, formulaCases, "The radical bar in the guide extends over -e."),
  write("math-repair-radical", "Repair a Misread Radical", "The required formula is a = b + sqrt((c+3)/(2+d) - e). Given doubles b,c,d,e with valid inputs, replace the shown declaration with a correct declaration of double a.", "double a = b + Math.sqrt((c + 3) / (2 + d) - e);", formulaSpec, formulaCases, "Move the closing parenthesis to match the extent of the square root.", "double a = b + Math.sqrt((c + 3) / (2 + d)) - e;"),
  write("math-root-outside", "Variation: The Subtraction Is Now Outside", "Given doubles x, y and z (y > 0, x >= 0), declare double value for sqrt(x/y) - z. Here the subtraction is OUTSIDE the radical.", "double value = Math.sqrt(x / y) - z;", { types: { x: "double", y: "double", z: "double" }, resultVariable: "value", resultType: "double" }, numericCases([{ x: 18, y: 2, z: 1 }, { x: 1, y: 4, z: 2 }, { x: 0, y: 1, z: -3 }], v => Math.sqrt(Number(v.x) / Number(v.y)) - Number(v.z)), "This contrast changes grouping, not just numbers."),
  write("math-inverse-formula", "Combine a Power with a Root", "Given double x, declare double result for (x squared + 1) divided by sqrt(x squared + 4).", "double result = (x*x + 1) / Math.sqrt(x*x + 4);", { types: { x: "double" }, resultVariable: "result", resultType: "double" }, numericCases([{ x: 0 }, { x: 2 }, { x: -3 }, { x: .5 }], v => (Number(v.x) ** 2 + 1) / Math.sqrt(Number(v.x) ** 2 + 4)), "The entire numerator needs grouping before division.", undefined, "Challenge"),
  write("math-sine", "Convert Degrees Before a Trig Call", "Given double degrees, declare double verticalFraction containing the sine of that angle. The input is in degrees, so convert to radians before calling sin.", "double verticalFraction = Math.sin(Math.toRadians(degrees));", { types: { degrees: "double" }, resultVariable: "verticalFraction", resultType: "double" }, numericCases([0, 30, 90, -30].map(degrees => ({ degrees })), v => Math.sin(Number(v.degrees) * Math.PI / 180)), "The sine method expects radians, not degrees."),
  output("random-endpoint", "Trace Near the Excluded Upper Bound", "double r = 0.9999;\nSystem.out.println((int) (r * 100));", "99", "The scaled value is below 100, so truncation cannot produce 100."),
  write("random-repair", "Repair the Early-Cast Bug", "Declare int digit uniformly from 0 through 9 using Math.random. Replace the broken declaration.", "int digit = (int) (Math.random() * 10);", { resultVariable: "digit", resultType: "int", requiredCalls: ["Math.random"] }, [0, .09999, .1, .59, .99999].map(r => ({ random: [r], result: Math.floor(r * 10) })), "Multiply the fractional sample before casting it.", "int digit = (int) Math.random() * 10;"),
  write("random-shift", "Build a New Inclusive Range", "Declare int selected uniformly from -3 through 4 inclusive using Math.random.", "int selected = (int) (Math.random() * 8) - 3;", { resultVariable: "selected", resultType: "int", requiredCalls: ["Math.random"] }, [0, .12499, .125, .4, .5, .99999].map(r => ({ random: [r], result: Math.floor(r * 8) - 3 })), "Count eight choices. Shift after truncating the nonnegative scaled sample.", undefined, "Challenge"),
  write("random-generality", "Retrieve a General Random Range", "Given int low and high (-100 <= low <= high <= 100), declare int result uniformly from low through high inclusive using Math.random.", "int result = low + (int) (Math.random() * (high - low + 1));", { types: { low: "int", high: "int" }, resultVariable: "result", resultType: "int", requiredCalls: ["Math.random"] }, [{ low: 5, high: 5, r: .9 }, { low: 10, high: 12, r: .99999 }, { low: -3, high: 2, r: .4 }, { low: -3, high: 2, r: 0 }, { low: 0, high: 9, r: .1 }].map(({ low, high, r }) => ({ values: { low, high }, random: [r], result: low + Math.floor(r * (high - low + 1)) })), "Inclusive endpoints require one more choice than high-low.", undefined, "Challenge")
]);

