group("Q6 · pages 5 and 10; Lecture 12", "files", {
  eyebrow: "Guide Q6 · read, transform, save, close", title: "Scanner Input, File Programs, and Resources",
  lead: "A Scanner can read typed values from the keyboard or from a File. PrintWriter writes to a file using the same print/println idea as console output. For exactly three input integers, three reads are enough: no loop is needed. The guide's rule increments all three inputs, so 3 10 3 must become 4, 11, 4; its printed final 3 is a typo.",
  examples: [{ label: "A complete two-value file example", code: full("SumFile", 'Scanner data = new Scanner(new File("pair.txt"));\nint first = data.nextInt();\nint second = data.nextInt();\nPrintWriter saved = new PrintWriter("sum.txt");\nsaved.println(first + second);\ndata.close();\nsaved.close();', true), note: "File, PrintWriter and FileNotFoundException come from java.io. Scanner comes from java.util. The exception phrase on main is setup boilerplate for opening files." }, { label: "Preserve a whole line after a number", code: "Scanner input = new Scanner(System.in);\nint age = input.nextInt();\ninput.nextLine(); // consume the remainder of that numeric line\nString name = input.nextLine();", note: "Token reads leave the newline behind. nextLine reads the remaining line, even when it is empty." }],
  rules: ["A relative filename such as numbers.txt is resolved in the working directory; it is not keyboard input.", "Opening PrintWriter for an existing file overwrites the old contents.", "Closing the writer completes buffered output. Close the file Scanner after its last read too.", "In practice, files are provided to the grader virtually; you do not need to create or upload files yourself."]
}, [
  select("file-source", "Choose File Input", "Which setup reads from numbers.txt?", 'Scanner data = new Scanner(new File("numbers.txt"));', ['Scanner data = new Scanner(System.in);', 'PrintWriter data = new PrintWriter("numbers.txt");', 'System.out.println("numbers.txt");'], "The Scanner's constructor selects its input source."),
  select("file-import", "Retrieve the File-Opening Setup", "A complete main opens a Scanner on a File. Which addition supplies the checked-exception setup taught in Lecture 12?", "Import java.io.FileNotFoundException and declare throws FileNotFoundException on main", ["Put throws on the import statement", "Replace Scanner with System.out", "Declare every input variable double"], "This phrase belongs on the main method header."),
  fileReadTrace,
  output("file-expected-transform", "Study Guide Q6: Correct the Example's Last Value", "int a = 3, b = 10, c = 3;\nSystem.out.println(a + 1);\nSystem.out.println(b + 1);\nSystem.out.println(c + 1);", "4\n11\n4", "The same increment applies to c; do not copy the study guide's output typo.", "Warm-up"),
  write("file-save-fragment", "Retrieve a Writer and Close It", "Inside a main method with file exception setup and imports already provided, create a writer for ready.txt, write Ready on its own line, and close the writer.", 'PrintWriter saved = new PrintWriter("ready.txt");\nsaved.println("Ready");\nsaved.close();', { requireClose: true }, [{ outputFiles: { "ready.txt": "Ready" } }], "Retrieve the writer constructor, output call and close call."),
  anchored("guide-files", fileIncrement),
  write("file-offset", "Use a Different Transformation", "Write OffsetFile.java. readings.txt contains exactly three ints. Subtract 2 from each and write the results to adjusted.txt, one per line. Include the complete program, imports and file-opening exception setup. Close both file resources.", full("OffsetFile", 'Scanner data = new Scanner(new File("readings.txt"));\nint first = data.nextInt();\nint second = data.nextInt();\nint third = data.nextInt();\nPrintWriter saved = new PrintWriter("adjusted.txt");\nsaved.println(first - 2);\nsaved.println(second - 2);\nsaved.println(third - 2);\ndata.close();\nsaved.close();', true), { className: "OffsetFile", requireClose: true }, [{ files: { "readings.txt": "3 10 3" }, outputFiles: { "adjusted.txt": "1\n8\n1" } }, { files: { "readings.txt": "-1 0 2" }, outputFiles: { "adjusted.txt": "-3\n-2\n0" } }, { files: { "readings.txt": "7 -4 11" }, outputFiles: { "adjusted.txt": "5\n-6\n9" } }], "Make sure each output is based on the corresponding input, including the third one."),
  write("file-aggregate", "Change the Relationship Between Inputs and Outputs", "Write TotalAverage.java. values.txt contains exactly three ints. Write their total to the first line of summary.txt and their mathematical average to the second line. Print the average as a double, including .0 for a whole average. Include file setup and close both resources.", full("TotalAverage", 'Scanner data = new Scanner(new File("values.txt"));\nint a = data.nextInt(), b = data.nextInt(), c = data.nextInt();\nint total = a + b + c;\nPrintWriter saved = new PrintWriter("summary.txt");\nsaved.println(total);\nsaved.println(total / 3.0);\ndata.close();\nsaved.close();', true), { className: "TotalAverage", requireClose: true }, [{ files: { "values.txt": "2 3 4" }, outputFiles: { "summary.txt": "9\n3.0" } }, { files: { "values.txt": "1 1 2" }, outputFiles: { "summary.txt": "4\n1.3333333333333333" } }, { files: { "values.txt": "-4 0 1" }, outputFiles: { "summary.txt": "-3\n-1.0" } }], "This file needs an aggregate and a fractional calculation, not three copied transformations."),
  write("file-range", "Combine File Input with a Validated Decision", "Write ScoreReport.java. score.txt contains one int. Write Invalid to result.txt outside 0–100; otherwise Pass for 70 or more, or Retry below 70. Include file setup and close both file resources. No console output is required.", full("ScoreReport", 'Scanner data = new Scanner(new File("score.txt"));\nint score = data.nextInt();\nPrintWriter saved = new PrintWriter("result.txt");\nif (score < 0 || score > 100) { saved.println("Invalid"); }\nelse if (score >= 70) { saved.println("Pass"); }\nelse { saved.println("Retry"); }\ndata.close();\nsaved.close();', true), { className: "ScoreReport", requireClose: true }, [-1, 0, 69, 70, 100, 101].map(score => ({ files: { "score.txt": String(score) }, outputFiles: { "result.txt": score < 0 || score > 100 ? "Invalid" : score >= 70 ? "Pass" : "Retry" } })), "Changing the output destination does not change the decision boundaries."),
  output("scanner-newline", "Find the Empty Remainder", 'Scanner input = new Scanner(System.in);\nint age = input.nextInt();\nString name = input.nextLine();\nSystem.out.println("[" + name + "]");', "[]", "The numeric token ends before the newline.", "Apply", "Keyboard input is two lines: 20, then Alice Smith. What prints?"),
  write("scanner-record", "Build a Mixed Number-and-Line Program", "Write NameRecord.java. Read an int age on one line and a full name on the next. Print NAME (AGE). Preserve spaces inside the name. Optional prompts may precede input.", full("NameRecord", 'Scanner input = new Scanner(System.in);\nint age = input.nextInt();\ninput.nextLine();\nString name = input.nextLine();\nSystem.out.println(name + " (" + age + ")");'), { className: "NameRecord" }, [{ input: "20\nAlice Smith\n", output: "Alice Smith (20)" }, { input: "18\nMary Ann Lee\n", output: "Mary Ann Lee (18)" }, { input: "0\nDan\n", output: "Dan (0)" }], "Do not lose either the next line or the spaces inside it.")
]);
