const guideStrings = 'String a = "Hello";\nString b = "World";';
group("Q7 · pages 5 and 10; Lecture 11", "strings", {
  eyebrow: "Guide Q7 · value plus type, or an error", title: "String Results, Return Types, Comparisons, and Errors",
  lead: "The guide asks for both a result and its type. charAt returns a char; substring and concat return String; compareTo returns int. For compareTo the question may only need its sign. Check the first differing character's code: uppercase and lowercase letters do not occupy the same positions. A valid-looking method call can still fail at runtime when its index is out of range.",
  concepts: [{ label: "Indexes", detail: "The first index is 0 and the last is length()-1. charAt(length()) fails. substring(start,end) includes start and excludes end; end may equal length()." }, { label: "Returned text", detail: "concat, trim, substring and case conversions return a String. They do not change the original variable unless you assign the returned value." }, { label: "Content and identity", detail: "equals compares text; == compares references. Assigning one String variable to another copies its reference. Reassigning one variable does not reassign the other." }, { label: "Character codes", detail: "For these basic characters: '0'=48, 'A'=65, 'a'=97. Arithmetic involving char normally produces int; cast back to char when a variable-based result must be stored as char." }],
  examples: [{ label: "Keep value and type together", code: 'String word = "Java";\n// word.charAt(1)       -> a, char\n// word.substring(1,2)  -> a, String\n// word.substring(4)    -> empty String\n// word.charAt(4)       -> runtime error', note: "The same visible letter can have different types. Empty text is still a valid String." }, { label: "Compare the first differing code", code: 'String first = "A";\nString second = "a";\nSystem.out.println(first.compareTo(second)); // -32', note: "A negative result means before, zero means equal contents, positive means after. It is not restricted to -1 or 1." }],
  rules: ["For value/type answers use VALUE | TYPE; quotes around the value are optional.", "For a sign question, enter negative, zero, or positive as requested.", "A runtime bounds error is different from assigning a char into a String variable, which is a compile-time type error."]
}, [
  typed("string-guide-concat", "Study Guide Q7a: Chained Concatenation", guideStrings, "a.concat(b).concat(b)", "HelloWorldWorld", "String", "Each call returns text that becomes the next receiver.", "Warm-up"),
  typed("string-guide-substring", "Study Guide Q7b: An Exclusive Ending Index", guideStrings, "a.substring(1, 3)", "el", "String", "Include indexes 1 and 2; exclude index 3."),
  typed("string-guide-char", "Study Guide Q7c: A Character Result", guideStrings, "b.charAt(1)", "o", "char", "The first index is zero."),
  select("string-guide-bounds", "Study Guide Q7d: Check the Last Legal Index", "What happens when the expression is evaluated?", "Runtime error: index 5 is outside World", ["Returns d as char", "Returns an empty String", "Returns d as String"], "World has length 5, so its last character is index 4.", guideStrings + "\nb.charAt(5)"),
  { ...output("string-guide-order", "Study Guide Q7e: Lexicographic Sign", guideStrings + "\n// Evaluate a.compareTo(b)", "negative", "H has a lower code than W.", "Apply", "Give only the sign of a.compareTo(b): negative, zero, or positive."), validate: s => /^(negative|negative integer)$/i.test(s.trim()) },
  { ...output("string-guide-case", "Study Guide Q7f: Change Case Before Comparing", guideStrings + "\n// Evaluate a.toLowerCase().compareTo(b)", "positive", "The lowercase h has a higher code than uppercase W.", "Apply", "Give only the sign of a.toLowerCase().compareTo(b): negative, zero, or positive."), validate: s => /^(positive|positive integer)$/i.test(s.trim()) },
  typed("string-empty", "An End Position Can Produce Empty Text", 'String word = "Java";', "word.substring(word.length())", "", "String", "substring may start at the position immediately after the last character."),
  typed("string-length", "A Size Is Not Text", 'String word = "Java";', "word.length()", "4", "int", "length returns an integer count."),
  typed("string-code", "Character Arithmetic Uses Codes", "char digit = '7';", "digit - '0'", "7", "int", "Subtract the code for '0', not the number zero."),
  typed("string-char-plus", "Adding Characters Does Not Join Text", "char a = '2';\nchar b = '3';", "a + b", "101", "int", "The two codes are 50 and 51."),
  output("string-unchanged", "Discarding a Return Value Leaves the Original", 'String s = "Java";\ns.toUpperCase();\nSystem.out.println(s);\ns = s.toUpperCase();\nSystem.out.println(s);', "Java\nJAVA", "Only the second call's result is stored."),
  output("string-references", "Reassign One Reference", 'String first = "Java";\nString second = first;\nfirst = first.toUpperCase();\nSystem.out.println(first);\nSystem.out.println(second);\nSystem.out.println(first.equals(second));', "JAVA\nJava\nfalse", "second still refers to the original text."),
  select("string-compile-error", "Differentiate a Type Error from a Bounds Error", "Why does this declaration fail?", "charAt returns char, which cannot be assigned directly to String", ["Index 0 is outside Java", "charAt returns int only", "All String methods require a Scanner"], "The index is valid; the destination type is wrong.", 'String text = "Java";\nString first = text.charAt(0);'),
  write("string-extract", "Retrieve a Substring from Requirements", "Given String code with at least 4 characters, declare String middle containing its second and third characters.", "String middle = code.substring(1, 3);", { types: { code: "String" }, resultVariable: "middle", resultType: "String" }, ["ABCD", "Java", "q12xyz"].map(code => ({ values: { code }, result: code.slice(1, 3) })), "Convert human positions to zero-based indexes, then exclude the ending index."),
  write("string-normalize", "Prepare Text for a Case-Independent Menu", "Given String raw containing a nonempty word possibly surrounded by spaces, declare String choice with those surrounding spaces removed and all letters lowercase.", "String choice = raw.trim().toLowerCase();", { types: { raw: "String" }, resultVariable: "choice", resultType: "String" }, ["  FEET  ", "Miles", " inches "].map(raw => ({ values: { raw }, result: raw.trim().toLowerCase() })), "Store the returned text; calling the methods alone does not change raw."),
  write("string-safe-index", "Validate Before Reading a Character", "Given String text and int index, print Invalid when index is outside the valid character positions; otherwise print that character. Empty Strings are possible. Decide the structure yourself.", 'if (index < 0 || index >= text.length()) { System.out.println("Invalid"); }\nelse { System.out.println(text.charAt(index)); }', { types: { text: "String", index: "int" } }, [{ text: "Java", index: -1 }, { text: "Java", index: 0 }, { text: "Java", index: 3 }, { text: "Java", index: 4 }, { text: "", index: 0 }].map(v => ({ values: v, output: v.index < 0 || v.index >= v.text.length ? "Invalid" : v.text[v.index] })), "Check validity before calling charAt; the empty String has no legal character index.", undefined, "Challenge")
]);
// Sign/typed questions are checked independently using the actual expression,
// while the student still supplies the value plus type or only the requested sign.
studyGuideTraceFixtures.set(id("string-guide-order"), { code: guideStrings + '\nSystem.out.println(a.compareTo(b));', output: "-15" });
studyGuideTraceFixtures.set(id("string-guide-case"), { code: guideStrings + '\nSystem.out.println(a.toLowerCase().compareTo(b));', output: "17" });
for (const q of studyGuideGroups.at(-1)!.questions.filter(q => q.kind === "Predict value and type")) {
  const [declarations, expression] = q.code!.split("\n// Expression to evaluate:\n");
  const fixtureType = q.answer!.split(" | ").at(-1)!;
  let value = q.answer!.slice(0, q.answer!.lastIndexOf(" | "));
  if (value === '""') value = "";
  studyGuideTraceFixtures.set(q.id, { code: declarations + `\nSystem.out.println(${expression});`, output: value });
  // Type-specific assignment is a separate compile check, even when char/String print alike.
  studyGuideTraceFixtures.set(`${q.id}-type`, { code: declarations + `\n${fixtureType} actual = ${expression};`, output: "" });
}

